#!/usr/bin/env node
/**
 * ego-lite laptop installer (generated by bridge/scripts/build-installer.mjs).
 *
 * Run this on your own laptop (macOS or Windows). It unpacks the bridge, checks
 * that ego lite is installed and its `ego-browser` command is on PATH, then
 * connects out to the relay so the agent can drive your browser.
 *
 * No inbound port is opened. The agent can only run the pinned tasks embedded
 * below; it cannot send code.
 *
 *   node egolite-bridge-install.mjs            # install + connect
 *   node egolite-bridge-install.mjs --check    # diagnose only
 *   node egolite-bridge-install.mjs --dir ~/ego-bridge
 *   node egolite-bridge-install.mjs --fixture  # also serve the local demo app
 */

import { spawn, spawnSync } from "node:child_process";
import { gunzipSync } from "node:zlib";
import { existsSync, mkdirSync, writeFileSync } from "node:fs";
import { homedir, platform as osPlatform, release } from "node:os";
import { dirname, join, resolve } from "node:path";

const BUNDLE = "";
const RELAY = "ws://127.0.0.1:8080/bridge";
const TOKEN = "fddead14c634a331c2fa22f3e36cc58db805a4a43ac4e7a2";
const TASK_COUNT = 8;
const BUILT_AT = "2026-11-05T08:16:47.729Z";

if (typeof WebSocket === "undefined") {
  console.error(
    `This installer needs Node.js 22 or newer (found ${process.version}).\n` +
      "Install it with `nvm install 22` (or https://nodejs.org/) and rerun.",
  );
  process.exit(1);
}

const args = parseArgs(process.argv.slice(2));
const verbose = Boolean(args.verbose);
const isWindows = process.platform === "win32";
const dir = expand(args.dir || join(homedir(), ".ego-bridge"));
const stateFile = join(dir, "bridge.json");

log(`ego-lite laptop installer · ${TASK_COUNT} tasks · built ${BUILT_AT}`);

// --------------------------------------------------------------------- unpack

const files = JSON.parse(gunzipSync(Buffer.from(BUNDLE, "base64")).toString("utf8"));
const unpacked = {};
for (const [relativePath, content] of Object.entries(files)) {
  const destination = join(dir, ...relativePath.split("/"));
  mkdirSync(dirname(destination), { recursive: true });
  writeFileSync(destination, content);
  unpacked[relativePath] = destination;
}
mkdirSync(join(dir, "tasks"), { recursive: true });
writeFileSync(
  stateFile,
  JSON.stringify({ relay: RELAY, token: TOKEN, installedAt: new Date().toISOString(), tasks: TASK_COUNT }, null, 2),
);
log(`unpacked into ${dir}`);

// ---------------------------------------------------------------------- checks

function findEgoBrowser() {
  const candidates = [];
  if (process.env.EGO_BROWSER_BIN) candidates.push(process.env.EGO_BROWSER_BIN);
  const probe = spawnSync(isWindows ? "where" : "sh", isWindows ? ["ego-browser"] : ["-c", "command -v ego-browser"], {
    encoding: "utf8",
  });
  if (probe.status === 0 && probe.stdout.trim()) candidates.push(probe.stdout.trim().split(/\r?\n/)[0]);
  candidates.push(join(homedir(), ".local", "bin", isWindows ? "ego-browser.cmd" : "ego-browser"));
  for (const candidate of candidates) {
    if (candidate && existsSync(candidate)) return candidate;
  }
  return null;
}

const egoBrowser = findEgoBrowser();
const egoLiteInstalled = Boolean(egoBrowser) ||
  (isWindows
    ? existsSync(join(process.env.LOCALAPPDATA || "", "ego lite"))
    : existsSync("/Applications/ego lite.app") || existsSync(join(homedir(), "Applications", "ego lite.app")));

console.log("");
console.log(`  platform        ${osPlatform()} ${release()} (${process.arch})`);
console.log(`  node            ${process.version}`);
console.log(`  ego lite app    ${egoLiteInstalled ? "found" : "NOT FOUND"}`);
console.log(`  ego-browser     ${egoBrowser || "NOT ON PATH"}`);
console.log(`  relay           ${RELAY}`);
console.log(`  tasks           ${TASK_COUNT}`);
console.log(`  install dir     ${dir}`);
console.log("");

if (!egoLiteInstalled || !egoBrowser) {
  console.error(
    [
      "ego lite is not ready on this machine.",
      "",
      "  1. Download and open it: https://lite.ego.app/",
      "     macOS:  https://cdn.ego.app/setup/macos/arm64/egolite-Y7MbxKIuhzFB.dmg  (Apple Silicon)",
      "             https://cdn.ego.app/setup/macos/x64/egolite-Y7MbxKIuhzFB.dmg    (Intel)",
      "     Windows: https://cdn.ego.app/setup/windows/x64/egoliteSetup-Y7MbxKIuhzFB.exe",
      "  2. Finish onboarding in the app (this registers `ego-browser` on PATH).",
      "     Say yes to importing Chrome data if you want your logins available.",
      "  3. Open a NEW terminal, then rerun this installer.",
      "",
      "Already installed but `ego-browser` still not found?",
      isWindows
        ? "  Open a new PowerShell/cmd window — PATH changes only reach new windows."
        : '  export PATH="$HOME/.local/bin:$PATH"',
    ].join("\n"),
  );
  process.exit(1);
}

// A real smoke command against the local browser, before touching the network.
const smoke = spawnSync(egoBrowser, ["nodejs", "-e", "console.log('ego-browser ready')"], {
  encoding: "utf8",
  timeout: 120_000,
});
if (smoke.status !== 0) {
  console.error("`ego-browser nodejs` did not run. Output:");
  console.error((smoke.stdout || "") + (smoke.stderr || ""));
  process.exit(1);
}
log(`local check: ${smoke.stdout.trim().split(/\r?\n/).pop()}`);

if (args.check) {
  log("--check only: environment looks good, not connecting.");
  process.exit(0);
}

// ------------------------------------------------------------------- fixtures

if (args.fixture) {
  const fixture = unpacked["fixtures/orders-server.mjs"];
  const child = spawn(process.execPath, [fixture], { stdio: "inherit" });
  console.log(`[laptop] demo back office on http://127.0.0.1:8787 (pid ${child.pid})`);
  process.on("exit", () => child.kill());
}

// --------------------------------------------------------------------- bridge

log(`connecting to ${RELAY}`);
const bridge = spawn(
  process.execPath,
  [unpacked["laptop/bridge.mjs"], "--relay", RELAY, "--token", TOKEN, ...(verbose ? ["--verbose"] : [])],
  {
    stdio: "inherit",
    env: { ...process.env, EGO_BROWSER_BIN: egoBrowser, EGO_BRIDGE_VERBOSE: verbose ? "1" : "" },
  },
);
process.on("SIGINT", () => {
  bridge.kill();
  process.exit(0);
});
bridge.on("exit", (code) => process.exit(code ?? 0));

// ------------------------------------------------------------------- helpers

function expand(path) {
  if (path.startsWith("~")) return resolve(homedir(), path.slice(1));
  return resolve(path);
}

function log(message) {
  console.error(`[install] ${message}`);
}

function parseArgs(argv) {
  const parsed = {};
  for (let i = 0; i < argv.length; i += 1) {
    const arg = argv[i];
    if (!arg.startsWith("--")) continue;
    const key = arg.slice(2);
    const next = argv[i + 1];
    if (next && !next.startsWith("--")) {
      parsed[key] = next;
      i += 1;
    } else {
      parsed[key] = true;
    }
  }
  return parsed;
}
